-- unself-core（PostgreSQL 变体）：核心库初始表结构
--
-- 与 core/0001_init.sql 同一逻辑迁移，语义逐条对齐；方言差异：
--   - 文本时间默认值从 `datetime('now')` 换成 to_char(now() AT TIME ZONE 'UTC', ...)，
--     落库形状仍是 `YYYY-MM-DD HH:MM:SS`（与 D1 / node:sqlite 一致）；
--   - `INSERT OR IGNORE` → `INSERT … ON CONFLICT DO NOTHING`；
--   - `INTEGER PRIMARY KEY AUTOINCREMENT` → `INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY`。

CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  issuer TEXT NOT NULL,
  sub TEXT NOT NULL,
  display_name TEXT,
  email TEXT,
  personal_email TEXT,
  role TEXT NOT NULL DEFAULT 'user',
  status TEXT NOT NULL DEFAULT 'active',
  created_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')),
  UNIQUE(issuer, sub)
);

CREATE TABLE IF NOT EXISTS invites (
  token_hash TEXT PRIMARY KEY,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'consumed', 'expired')),
  personal_email TEXT NOT NULL,
  email_prefix TEXT NOT NULL,
  display_name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')),
  expires_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS notification_types (
  type TEXT PRIMARY KEY,
  template TEXT NOT NULL,
  in_app INTEGER NOT NULL DEFAULT 1,
  email INTEGER NOT NULL DEFAULT 0
);

INSERT INTO notification_types (type, template, in_app, email) VALUES
  ('invite_result', '邀请申请结果', 1, 1),
  ('account_ready', '账号已开通', 1, 1),
  ('module_toggled', '模块状态已更新', 1, 0)
ON CONFLICT DO NOTHING;

CREATE TABLE IF NOT EXISTS notifications (
  id TEXT PRIMARY KEY,
  user_id TEXT,
  invited_email TEXT,
  type TEXT NOT NULL,
  payload TEXT NOT NULL,
  is_read INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS module_registry (
  id TEXT PRIMARY KEY,
  enabled INTEGER NOT NULL DEFAULT 0,
  version TEXT,
  manifest_json TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS acl (
  resource TEXT NOT NULL,
  user_id TEXT NOT NULL,
  perm TEXT NOT NULL,
  PRIMARY KEY(resource, user_id, perm)
);

CREATE TABLE IF NOT EXISTS audit_log (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  actor TEXT NOT NULL,
  action TEXT NOT NULL,
  target TEXT,
  created_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'))
);
